    public function register_assets(){wp_register_style('sc-library-workspace-continuity-v4333',SC_LIBRARY_URL.'assets/css/sc-library-workspace-continuity-v4333.css',array(),SC_LIBRARY_VERSION);wp_register_script('sc-library-workspace-continuity-v4333',SC_LIBRARY_URL.'assets/js/sc-library-workspace-continuity-v4333.js',array(),SC_LIBRARY_VERSION,true);}
    public static function contract(){return array('schema'=>self::SCHEMA,'library_account'=>'shared-sustainable-catalyst-account','workspace_account'=>'shared-sustainable-catalyst-account','separate_workspace_identity'=>false,'transport'=>'signed-expiring-reference-handoff','outbound_requires_user_action'=>true,'inbound_requires_user_action'=>true,'library_records_remain_canonical'=>true,'workspace_records_remain_canonical_in_workspace'=>true,'references_only'=>true,'copy_private_binary_files'=>false,'copy_underlying_library_records'=>false,'automatic_workspace_write'=>false,'automatic_library_write'=>false,'automatic_publication'=>false,'automatic_evidence_promotion'=>false);}
