    private static function clean_text($v,$l=220){$v=trim(preg_replace('/\s+/',' ',sanitize_text_field((string)$v)));return function_exists('mb_substr')?mb_substr($v,0,$l):substr($v,0,$l);}
    private static function b64url($v){return rtrim(strtr(base64_encode((string)$v),'+/','-_'),'=');}
