    public static function context_catalog_for_user($uid){$uid=absint($uid);$items=array();if(!$uid||!class_exists('SC_Library_Unified_Research_Projects_Source_Bundles'))return $items;foreach(SC_Library_Unified_Research_Projects_Source_Bundles::projects_for_user($uid) as $pid){$pid=absint($pid);$id=class_exists('SC_Library_Cross_Product_Research_Handoffs')?SC_Library_Cross_Product_Research_Handoffs::project_identity($pid,true):array();$items[]=array('scope'=>'project','scope_id'=>(string)$pid,'project_id'=>$pid,'urn'=>(string)($id['urn']??''),'label'=>get_the_title($pid)?:'Research Project '.$pid);foreach(SC_Library_Unified_Research_Projects_Source_Bundles::bundles_for_project($pid) as $b)$items[]=array('scope'=>'source_bundle','scope_id'=>(string)($b['bundle_id']??''),'project_id'=>$pid,'urn'=>(string)($b['urn']??''),'label'=>sprintf('%s / %s',get_the_title($pid),(string)($b['title']??'Source bundle')));}
        if(class_exists('SC_Library_Reading_Notebook_Annotations')){$st=SC_Library_Reading_Notebook_Annotations::state_for_user($uid);foreach((array)($st['notebooks']??array()) as $n){$pid=absint($n['project_context']['project_id']??0);if(!$pid||!self::project_owns_user($pid,$uid))continue;$items[]=array('scope'=>'reading_notebook','scope_id'=>(string)($n['notebook_id']??''),'project_id'=>$pid,'urn'=>(string)($n['urn']??''),'label'=>sprintf('%s / Notebook: %s',get_the_title($pid),(string)($n['title']??'Reading notebook')));}}
        if(class_exists('SC_Library_Evidence_Matrix_Claim_Intelligence')){$st=SC_Library_Evidence_Matrix_Claim_Intelligence::state_for_user($uid);foreach((array)($st['matrices']??array()) as $m){$pid=absint($m['project_context']['project_id']??0);if(!$pid||!self::project_owns_user($pid,$uid))continue;$items[]=array('scope'=>'evidence_matrix','scope_id'=>(string)($m['matrix_id']??''),'project_id'=>$pid,'urn'=>(string)($m['urn']??''),'label'=>sprintf('%s / Evidence: %s',get_the_title($pid),(string)($m['title']??'Evidence matrix')));}}return $items;}
    public static function selected_context($uid,$pid,$scope,$sid){$uid=absint($uid);$pid=absint($pid);$scope=sanitize_key($scope);$sid=self::clean_text($sid,100);if(!self::project_owns_user($pid,$uid))return new WP_Error('sc_workspace_project_forbidden',__('That Research Project is not available to this account.','sustainable-catalyst-library'),array('status'=>403));if(!in_array($scope,array('project','source_bundle','reading_notebook','evidence_matrix'),true))return new WP_Error('sc_workspace_scope_invalid',__('Choose a valid Library continuity scope.','sustainable-catalyst-library'),array('status'=>400));$identity=class_exists('SC_Library_Cross_Product_Research_Handoffs')?SC_Library_Cross_Product_Research_Handoffs::project_identity($pid,true):array();$c=array('schema'=>self::PACKET_SCHEMA,'scope'=>$scope,'scope_id'=>$sid,'project_id'=>$pid,'project_identity'=>$identity,'record'=>array(),'reference_catalog'=>array(),'contract'=>self::contract());
        if('project'===$scope){$st=SC_Library_Unified_Research_Projects_Source_Bundles::project_state($pid,$uid);if(is_wp_error($st))return $st;$c['record']=array('schema'=>$st['schema']??'','project_id'=>$pid,'title'=>$st['title']??get_the_title($pid),'research_question'=>$st['research_question']??'','status'=>$st['status']??'','references'=>$st['references']??array(),'source_bundles'=>$st['source_bundles']??array());$c['reference_catalog']=SC_Library_Unified_Research_Projects_Source_Bundles::reference_catalog_for_user($uid);}elseif('source_bundle'===$scope){$m=SC_Library_Unified_Research_Projects_Source_Bundles::bundle_manifest($pid,$sid,$uid);if(is_wp_error($m))return $m;$c['record']=$m;}elseif('reading_notebook'===$scope){$st=SC_Library_Reading_Notebook_Annotations::notebook_state(absint($sid),$uid);if(is_wp_error($st)||absint($st['project_context']['project_id']??0)!==$pid)return new WP_Error('sc_workspace_notebook_context_invalid',__('That notebook is not attached to this project.','sustainable-catalyst-library'),array('status'=>409));$c['record']=array('schema'=>$st['schema']??'','notebook_id'=>$st['notebook_id']??0,'urn'=>$st['urn']??'','title'=>$st['title']??'','project_context'=>$st['project_context']??array(),'notes'=>$st['notes']??array(),'annotations'=>$st['annotations']??array(),'updated_at'=>$st['updated_at']??'');}elseif('evidence_matrix'===$scope){$st=SC_Library_Evidence_Matrix_Claim_Intelligence::matrix_state(absint($sid),$uid);if(is_wp_error($st)||absint($st['project_context']['project_id']??0)!==$pid)return new WP_Error('sc_workspace_matrix_context_invalid',__('That evidence matrix is not attached to this project.','sustainable-catalyst-library'),array('status'=>409));$c['record']=array('schema'=>$st['schema']??'','matrix_id'=>$st['matrix_id']??0,'urn'=>$st['urn']??'','title'=>$st['title']??'','project_context'=>$st['project_context']??array(),'claims'=>$st['claims']??array(),'evidence_links'=>$st['evidence_links']??array(),'diagnostics'=>$st['diagnostics']??array(),'updated_at'=>$st['updated_at']??'');}$c['generated_at']=current_time('mysql',true);$c['generated_by']=$uid;$c['checksum']=hash('sha256',wp_json_encode($c));return $c;}
    public static function create_workspace_handoff_for_user($uid,$in){$uid=absint($uid);$pid=absint($in['project_id']??0);$scope=sanitize_key($in['scope']??'project');$sid=self::clean_text($in['scope_id']??('project'===$scope?(string)$pid:''),100);if(!$uid||!self::project_owns_user($pid,$uid))return new WP_Error('sc_workspace_project_forbidden',__('That Research Project is not available to this account.','sustainable-catalyst-library'),array('status'=>403));if(!class_exists('SC_Library_Cross_Product_Research_Handoffs'))return new WP_Error('sc_workspace_handoff_transport_missing',__('The Library handoff transport is unavailable.','sustainable-catalyst-library'),array('status'=>503));$ctx=self::selected_context($uid,$pid,$scope,$sid);if(is_wp_error($ctx))return $ctx;$params=array('continuity_scope'=>$scope,'continuity_scope_id'=>$sid,'continuity_checksum'=>$ctx['checksum'],'references_only'=>true);$r=SC_Library_Cross_Product_Research_Handoffs::create_handoff($pid,array('target_product'=>'workspace','handoff_type'=>'library-continuity','status'=>'sent','direction'=>'outbound','sections'=>array('project'),'request'=>array('instructions'=>self::clean_text($in['note']??'',500),'parameters'=>$params),'recipient_url'=>self::workspace_url(),'return_url'=>self::library_reopen_url($ctx),'issue_token'=>true,'token_days'=>7));if(is_wp_error($r))return $r;$d=is_array($r['delivery']??null)?$r['delivery']:array();$frag=array('schema'=>self::SCHEMA,'handoff_uuid'=>$r['uuid']??'','project_urn'=>$r['project_identity']['urn']??'','delivery_url'=>$d['delivery_url']??'','return_url'=>$r['return_url']??self::library_reopen_url($ctx),'expires'=>$d['expires_iso']??'');$r['workspace_launch_url']=self::workspace_url().'#sc-library-continuity='.rawurlencode(self::b64url(wp_json_encode($frag)));$r['continuity']=$ctx;$r['contract']=self::contract();return $r;}
    public function filter_workspace_bundle($bundle,$target,$type,$pid){if('workspace'!==$target||'library-continuity'!==$type||!is_array($bundle))return $bundle;$params=(array)($bundle['request']['parameters']??array());$scope=sanitize_key($params['continuity_scope']??'project');$sid=self::clean_text($params['continuity_scope_id']??(string)$pid,100);$ctx=self::selected_context(get_current_user_id(),$pid,$scope,$sid);if(!is_wp_error($ctx))$bundle['workspace_continuity']=$ctx;$bundle['continuity_contract']=self::contract();return $bundle;}
    public static function library_reopen_url($ctx){$base=class_exists('SC_Library_Canonical_Route_Identity')?SC_Library_Canonical_Route_Identity::canonical_url():home_url('/knowledge-libraries/');$scope=sanitize_key($ctx['scope']??'project');$sid=self::clean_text($ctx['scope_id']??'',100);$pid=absint($ctx['project_id']??0);$anchors=array('project'=>'research-projects','source_bundle'=>'research-projects','reading_notebook'=>'reading-notebooks','evidence_matrix'=>'evidence-matrix');$anchor=$anchors[$scope]??'research-projects';return add_query_arg(array('sc_library_project'=>$pid,'sc_library_scope'=>$scope,'sc_library_ref'=>$sid),$base).'#'.$anchor;}
    public static function resolve_reopen_reference($uid,$ref){$uid=absint($uid);$ref=self::clean_text($ref,320);foreach(self::context_catalog_for_user($uid) as $i){if($ref===(string)($i['urn']??'')||$ref===(string)($i['scope_id']??'')||$ref===$i['scope'].':'.$i['scope_id']){$ctx=array('scope'=>$i['scope'],'scope_id'=>$i['scope_id'],'project_id'=>$i['project_id']);return array('schema'=>self::REOPEN_SCHEMA,'found'=>true,'ref'=>$ref,'context'=>$ctx,'library_url'=>self::library_reopen_url($ctx),'label'=>$i['label'],'contract'=>self::contract());}}return array('schema'=>self::REOPEN_SCHEMA,'found'=>false,'ref'=>$ref,'library_url'=>class_exists('SC_Library_Canonical_Route_Identity')?SC_Library_Canonical_Route_Identity::canonical_url():home_url('/knowledge-libraries/'),'contract'=>self::contract());}
    public static function recent_workspace_handoffs($uid){$items=array();if(!class_exists('SC_Library_Unified_Research_Projects_Source_Bundles')||!class_exists('SC_Library_Cross_Product_Research_Handoffs'))return $items;foreach(SC_Library_Unified_Research_Projects_Source_Bundles::projects_for_user(absint($uid)) as $pid)foreach(SC_Library_Cross_Product_Research_Handoffs::handoffs_for_project($pid,self::MAX_RECENT_HANDOFFS) as $h)if('workspace'===(string)($h['target_product']??''))$items[]=$h;usort($items,static function($a,$b){return strcmp((string)($b['updated_at']??''),(string)($a['updated_at']??''));});return array_slice($items,0,self::MAX_RECENT_HANDOFFS);}
    public function register_rest_routes(){register_rest_route(self::REST_NAMESPACE,self::REST_ROUTE,array('methods'=>WP_REST_Server::READABLE,'permission_callback'=>array($this,'rest_signed_in'),'callback'=>array($this,'rest_state')));register_rest_route(self::REST_NAMESPACE,self::REST_ROUTE.'/handoffs',array('methods'=>WP_REST_Server::CREATABLE,'permission_callback'=>array($this,'rest_signed_in'),'callback'=>array($this,'rest_create_handoff')));register_rest_route(self::REST_NAMESPACE,self::REST_ROUTE.'/resolve',array('methods'=>WP_REST_Server::READABLE,'permission_callback'=>array($this,'rest_signed_in'),'callback'=>array($this,'rest_resolve')));}
    public function rest_signed_in(){return is_user_logged_in();} public function rest_state(){$uid=get_current_user_id();return rest_ensure_response(array('schema'=>self::SCHEMA,'version'=>self::VERSION,'workspace_url'=>self::workspace_url(),'contexts'=>self::context_catalog_for_user($uid),'recent_handoffs'=>self::recent_workspace_handoffs($uid),'contract'=>self::contract()));} public function rest_create_handoff(WP_REST_Request $r){$in=$r->get_json_params();$x=self::create_workspace_handoff_for_user(get_current_user_id(),is_array($in)?$in:array());return is_wp_error($x)?$x:rest_ensure_response($x);} public function rest_resolve(WP_REST_Request $r){return rest_ensure_response(self::resolve_reopen_reference(get_current_user_id(),$r->get_param('ref')));}
    private static function ajax_guard(){check_ajax_referer(self::NONCE_ACTION,'nonce');if(!is_user_logged_in())wp_send_json_error(array('message'=>__('Sign in to continue research into Workspace.','sustainable-catalyst-library')),401);return get_current_user_id();}
    public function ajax_create_workspace_handoff(){$uid=self::ajax_guard();$raw=self::clean_text(wp_unslash($_POST['context']??''),180);$p=explode('|',$raw,3);$x=self::create_workspace_handoff_for_user($uid,array('project_id'=>absint($p[0]??0),'scope'=>sanitize_key($p[1]??'project'),'scope_id'=>self::clean_text($p[2]??'',100),'note'=>wp_unslash($_POST['note']??'')));if(is_wp_error($x))wp_send_json_error(array('message'=>$x->get_error_message()),400);wp_send_json_success(array('message'=>__('Workspace continuity packet prepared.','sustainable-catalyst-library'),'handoff'=>$x));}
    public function shortcode($atts){$atts=shortcode_atts(array('title'=>'Library ↔ Workspace Continuity'),$atts,'sc_library_workspace_continuity');wp_enqueue_style('sc-library-workspace-continuity-v4333');wp_enqueue_script('sc-library-workspace-continuity-v4333');$signed=is_user_logged_in();$uid=$signed?get_current_user_id():0;$cat=$signed?self::context_catalog_for_user($uid):array();wp_localize_script('sc-library-workspace-continuity-v4333','SCLibraryWorkspaceContinuity',array('ajaxUrl'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce(self::NONCE_ACTION),'signedIn'=>$signed));ob_start();?><section class="sc-workspace-continuity" data-sc-workspace-continuity="v4.3.33"><header class="sc-workspace-continuity__hero"><div><p><?php esc_html_e('Shared-account research continuity','sustainable-catalyst-library'); ?></p><h3><?php echo esc_html($atts['title']); ?></h3><span><?php esc_html_e('Prepare an explicit signed reference packet for Workspace, then return to the same Library project, bundle, notebook, or evidence matrix without creating a second identity or copying the underlying research record.','sustainable-catalyst-library'); ?></span></div><aside><strong><?php esc_html_e('User-directed handoff','sustainable-catalyst-library'); ?></strong><span><?php esc_html_e('Nothing is written into Workspace or back into the Library automatically. The receiving product must explicitly accept the signed packet or return reference.','sustainable-catalyst-library'); ?></span></aside></header><?php if(!$signed):?><div class="sc-workspace-continuity__signin"><strong><?php esc_html_e('Sign in to continue private Library research into Workspace.','sustainable-catalyst-library'); ?></strong><a href="<?php echo esc_url(wp_login_url(class_exists('SC_Library_Canonical_Route_Identity')?SC_Library_Canonical_Route_Identity::canonical_url():home_url('/knowledge-libraries/'))); ?>"><?php esc_html_e('Sign in →','sustainable-catalyst-library'); ?></a></div><?php elseif(!$cat):?><p class="sc-workspace-continuity__empty"><?php esc_html_e('Create a Research Project first. Workspace continuity is project-anchored so source references, notebooks, and evidence stay tied to one stable research identity.','sustainable-catalyst-library'); ?></p><?php else:?><form data-sc-workspace-continuity-form><label><span><?php esc_html_e('Research context','sustainable-catalyst-library'); ?></span><select name="context" required><?php foreach($cat as $i):?><option value="<?php echo esc_attr($i['project_id'].'|'.$i['scope'].'|'.$i['scope_id']); ?>"><?php echo esc_html($i['label']); ?></option><?php endforeach;?></select></label><label><span><?php esc_html_e('Handoff note (optional)','sustainable-catalyst-library'); ?></span><textarea name="note" rows="2" maxlength="500" placeholder="<?php esc_attr_e('What do you want to continue doing in Workspace?','sustainable-catalyst-library'); ?>"></textarea></label><div class="sc-workspace-continuity__actions"><button type="submit"><?php esc_html_e('Prepare & Open Workspace','sustainable-catalyst-library'); ?></button><span data-sc-workspace-continuity-status aria-live="polite"></span></div></form><p class="sc-workspace-continuity__boundary"><?php esc_html_e('The launch token is short-lived and placed in the URL fragment generated by this v4.3.33 surface so it is not sent as a normal page query parameter. Workspace must explicitly consume the continuity fragment and retrieve the signed packet.','sustainable-catalyst-library'); ?></p><?php endif;?></section><?php return ob_get_clean();}
